mapper.select:
SELECT wo.*, m.name AS material_name, m.model AS material_model, m.standard AS material_standard, mc.name AS category_name, u.name AS basic_unit, u.ratio AS ratio, IFNULL(task_stats.total_tasks, 0) AS total_tasks, IFNULL(task_stats.completed_tasks, 0) AS completed_tasks, IFNULL(task_stats.pending_tasks, 0) AS pending_tasks, IFNULL(task_stats.in_progress_tasks, 0) AS in_progress_tasks, CASE WHEN wo.planned_quantity > 0 THEN ROUND((wo.actual_quantity / wo.planned_quantity) * 100, 2) ELSE 0 END AS completion_rate, CASE WHEN wo.estimated_cost > 0 THEN ROUND(((wo.actual_cost - wo.estimated_cost) / wo.estimated_cost) * 100, 2) ELSE 0 END AS cost_variance, cu.username AS create_user_name, uu.username AS update_user_name, CASE wo.source_type WHEN 'SALES_ORDER' THEN '销售订单' WHEN 'STOCK_PLAN' THEN '库存计划' WHEN 'MANUAL' THEN '手动创建' ELSE wo.source_type END AS source_type_name FROM jsh_production_work_order wo LEFT JOIN jsh_material m ON wo.product_id = m.id AND IFNULL(m.delete_flag, '0') != '1' LEFT JOIN jsh_material_category mc ON m.category_id = mc.id AND IFNULL(mc.delete_flag, '0') != '1' LEFT JOIN jsh_unit u ON wo.unit_id = u.id AND IFNULL(u.delete_flag, '0') != '1' LEFT JOIN jsh_user cu ON wo.create_user = cu.id AND IFNULL(cu.delete_flag, '0') != '1' LEFT JOIN jsh_user uu ON wo.update_user = uu.id AND IFNULL(uu.delete_flag, '0') != '1' LEFT JOIN ( SELECT work_order_id, COUNT(*) AS total_tasks, SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_tasks, SUM(CASE WHEN status = 'PENDING' THEN 1 ELSE 0 END) AS pending_tasks, SUM(CASE WHEN status = 'IN_PROGRESS' THEN 1 ELSE 0 END) AS in_progress_tasks FROM jsh_production_task WHERE IFNULL(delete_flag, '0') != '1' GROUP BY work_order_id ) task_stats ON wo.id = task_stats.work_order_id WHERE 1=1 AND IFNULL(wo.delete_flag, '0') != '1'
AND wo.work_order_number LIKE #{bindWorkOrderNumber}
AND wo.work_order_name LIKE #{bindWorkOrderName}
AND (wo.product_name LIKE #{bindProductName} OR m.name LIKE #{bindProductName})
AND wo.production_mode = #{productionMode}
AND wo.production_type = #{productionType}
AND wo.priority = #{priority}
AND wo.status = #{status}
AND wo.responsible_person LIKE #{bindResponsiblePerson}
AND wo.workshop_name LIKE #{bindWorkshopName}
AND wo.plan_start_time >= #{planStartTime}
AND wo.plan_end_time <= #{planEndTime}
AND wo.source_type = #{sourceType}
AND wo.source_number LIKE #{bindSourceNumber}
AND wo.tenant_id = #{tenantId}
ORDER BY wo.create_time DESC
LIMIT #{offset}, #{rows}

